function validateStoredEnvelope(data: unknown): StoredEnvelope | null {
  if (!data || typeof data !== 'object') return null;
  const obj = data as Record<string, unknown>;
  const totalAmount = Number(obj.totalAmount ?? 0);
  const packetCount = Number(obj.packetCount ?? 0);
  const openedCount = Number(obj.openedCount ?? 0);
  const remainingAmount = Number(obj.remainingAmount ?? 0);
  const expiryTime = Number(obj.expiryTime ?? 0);
  if (!Number.isFinite(totalAmount) || !Number.isFinite(packetCount) || !Number.isFinite(openedCount) || !Number.isFinite(remainingAmount) || !Number.isFinite(expiryTime)) return null;
  return { id: String(obj.id ?? ''), creator: String(obj.creator ?? ''), totalAmount, packetCount, openedCount, remainingAmount, bestLuckAddress: obj.bestLuckAddress ? String(obj.bestLuckAddress) : undefined, bestLuckAmount: obj.bestLuckAmount ? Number(obj.bestLuckAmount) : undefined, ready: Boolean(obj.ready), expiryTime, claimedByCurrentUser: Boolean(obj.claimedByCurrentUser) };
}
```

